export const DICTS = { en, pt, he, ru };

let current = 'en';
export function setLang(l) { current = DICTS[l] ? l : 'en'; return current; }
export function getLang() { return current; }
export function langInfo(l = current) { return LANGS.find(x => x.id === l) || LANGS[0]; }

export function t(key, vars) {
  let s = DICTS[current][key];
  if (s == null) s = en[key];
  if (s == null) return key;
  if (vars) s = s.replace(/\{(\w+)\}/g, (m, k) => (vars[k] != null ? vars[k] : m));
  return s;
}

// Localised label from a data.js {en,pt,he} object.
export function L(obj) {
  if (obj == null) return '';
  if (typeof obj === 'string') return obj;
  if (obj[current]) return obj[current];
  if (current === 'ru' && RU_DATA[obj.en]) return RU_DATA[obj.en];
  return obj.en || '';
}

export function fmtMoney(n, lang = current) {
  return new Intl.NumberFormat(langInfo(lang).locale, { style: 'currency', currency: 'EUR', maximumFractionDigits: 0 }).format(n);
}
export function fmtNum(n, digits = 2, lang = current) {
  return new Intl.NumberFormat(langInfo(lang).locale, { minimumFractionDigits: digits, maximumFractionDigits: digits }).format(n);
}
